export const code = async (inputs) => {
  // Тексты — во входе `texts` (ADR-0014), источник — i18n/ru.json.
  // Вердикт W49 (ADR-0027/ADR-0033, перенос из prototypes/scenarios.js:39-49):
  // гость — одна кнопка «События», свой текст без заголовка;
  // овнер — «События» + «Новое событие» сразу на форму #/manage/new;
  // кнопки сканера в чате нет — сканер только рядом с событием (STF-2).
  // W51 (решение владельца 2026-09-19): овнеру вернули вход в свой список —
  // «Панель администратора» сразу на #/manage (правка без команд, ADR-0025).
  // W52 (решение владельца 2026-09-19): у овнера первой кнопкой —
  // «Панель администратора», затем «События» и «Новое событие».
  // ADR-0034: этот шаг выполняется только когда профиль уже заполнен —
  // гейт стоит раньше (step_2/step_3), роли здесь ни при чём.
  // W73 (#125): обычный текст приходит сюда с fallback=true — преамбула
  // другая (menu.fallback_text), кнопки и лид те же, что у /start.
  // W68 (#120): у овнера четвёртая кнопка «Как сделать рассылку»
  // (колбэк menu:bcast_help, маршрут в tg-router); по колбэку меню отвечает
  // инструкцией из bcast.howto.* — тем же текстом, что таб «Рассылка» Mini App.
  // W103 (ADR-0041, решение владельца 2026-09-24): пока открыто окно хотя бы
  // одной викторины, кнопка «Викторина» (колбэк qz:start → флоу `quiz`) видна
  // ВСЕМ ролям: гостю и контролёру — первой строкой, организатору — после
  // его кнопок (первой у овнера остаётся «Панель администратора», W52).
  // Вне окна кнопки нет — мёртвых кнопок не держим.
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key, vars) => {
    let s = String(texts[key] === undefined || texts[key] === null ? key : texts[key]);
    if (vars) Object.keys(vars).forEach((k) => { s = s.split('{' + k + '}').join(String(vars[k])); });
    return s;
  };
  const str = (v) => String(v === undefined || v === null ? '' : v);
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = str(c.value);
      else out[fid] = str(c);
    });
    return out;
  };
  const parseIso = (s) => Date.parse(/[Zz]$/.test(s) || /[+-][0-9]{2}:?[0-9]{2}$/.test(s) ? s : s + 'Z');

  const telegramId = str(inputs.telegramId);
  const firstName = str(inputs.firstName).trim();
  const badPayload = inputs.badPayload === true || str(inputs.badPayload) === 'true';
  const fallback = inputs.fallback === true || str(inputs.fallback) === 'true';
  const callbackData = str(inputs.callbackData);
  const isHelp = callbackData === 'menu:bcast_help';
  const miniappUrl = str(inputs.miniappUrl);
  const base = miniappUrl.endsWith('/') ? miniappUrl.slice(0, -1) : miniappUrl;
  const nowMs = Date.now();

  // Организатор — есть строка в `staff` с telegram_id = пользователь (ADR-0024).
  // Это видимость, а не авторизация: правило прав решает manage-api.
  // Постфильтр по telegram_id повторяет фильтр шага (defense in depth, Q25).
  const isOwner = arr(inputs.staffRoleRecords).map(flat).some((r) => r.telegram_id === telegramId);

  // Контролёр — активная строка event_staff (пустой revoked_at) на ещё не
  // закончившееся опубликованное событие. Отдельной кнопки в чате больше нет:
  // сканер — рядом с событием в Mini App + кнопка на конкретное событие
  // в accept-карточке. Здесь флаг нужен только для текста и роли.
  const published = arr(inputs.publishedRecords).map(flat).filter((r) => r.status === 'published');
  const byId = {};
  published.forEach((r) => { byId[r.id] = r; });
  const notPast = (r) => {
    const endMs = parseIso(r.ends_at || r.starts_at || '');
    return isFinite(endMs) ? endMs > nowMs : true;
  };
  const isController = arr(inputs.staffRecords).map(flat)
    .some((r) => r.telegram_id === telegramId && r.revoked_at === '' && byId[r.event_id] && notPast(byId[r.event_id]));

  // W103 (ADR-0041): кнопка викторины — только пока открыто окно викторины.
  // Окно проверяется в CODE (диапазонные фильтры по DATE не работают, Q15).
  const activeQuiz = arr(inputs.quizRecords).map(flat).some((q) => {
    const st = parseIso(str(q.starts_at));
    const en = parseIso(str(q.ends_at));
    return isFinite(st) && isFinite(en) && nowMs >= st && nowMs <= en;
  });

  const preamble = fallback
    ? t('menu.fallback_text')
    : (badPayload
      ? t('start.bad_payload')
      : (firstName ? t('start.greeting', { name: firstName }) : t('start.greeting_anon')));

  // Порядок кнопок фиксирован, по одной в ряд. Двойная роль — объединение.
  const eventsBtn = [{ text: t('menu.btn.events'), web_app: { url: base + '/#/events' } }];
  const manageBtn = [{ text: t('menu.btn.manage'), web_app: { url: base + '/#/manage' } }];
  const newEventBtn = [{ text: t('menu.btn.new_event'), web_app: { url: base + '/#/manage/new' } }];
  const bcastHelpBtn = [{ text: t('menu.btn.bcast_help'), callback_data: 'menu:bcast_help' }];
  const quizBtn = [{ text: t('menu.btn.quiz'), callback_data: 'qz:start' }];
  // W103: в окне викторины кнопка есть у всех ролей; у гостя/контролёра —
  // первой, у организатора — после его кнопок (W52 не ломаем).
  const guestRows = activeQuiz ? [quizBtn, eventsBtn] : [eventsBtn];
  const ownerBase = [manageBtn, eventsBtn, newEventBtn, bcastHelpBtn];
  const ownerRows = activeQuiz ? ownerBase.concat([quizBtn]) : ownerBase;
  let rows;
  let lead;
  let role;
  if (isOwner && isController) {
    rows = ownerRows;
    lead = t('menu.lead_owner');
    role = 'owner_controller';
  } else if (isOwner) {
    rows = ownerRows;
    lead = t('menu.lead_owner');
    role = 'owner';
  } else if (isController) {
    rows = guestRows;
    lead = t('menu.lead_controller');
    role = 'controller';
  } else {
    rows = guestRows;
    lead = t('menu.lead_guest');
    role = 'guest';
  }

  // W68 (#120): колбэк кнопки «Как сделать рассылку». Отвечаем инструкцией
  // тем же меню-набором кнопок; гостю/контролёру (кнопки нет) — обычное меню.
  if (isHelp && isOwner) {
    const helpText = t('bcast.howto.title') + '\n'
      + t('bcast.howto.step1') + '\n'
      + t('bcast.howto.step2') + '\n'
      + t('bcast.howto.step3');
    return {
      text: helpText, reply_markup: { inline_keyboard: rows },
      isOwner: isOwner, isController: isController, role: role,
      badPayload: badPayload, fallback: fallback, help: true, buttons: rows.length
    };
  }

  return {
    text: preamble + '\n\n' + lead,
    reply_markup: { inline_keyboard: rows },
    isOwner: isOwner, isController: isController, role: role,
    badPayload: badPayload, fallback: fallback, help: false, buttons: rows.length
  };
};

export const code = async (inputs) => {
  const cardMessageId = Number(inputs.cardMessageId);
  const draft = {
    eventId: '',
    utm: '',
    cardMessageId: isFinite(cardMessageId) && cardMessageId > 0 ? cardMessageId : 0,
    step: 'ob_consent'
  };
  return { draft: JSON.stringify(draft), cardMessageId: draft.cardMessageId };
};

export const code = async (inputs) => {
  // ADR-0034: онбординг без диплинка — та же why-карточка, что у reg-start
  // при входе по ссылке события, но без фактов события (их тут нет).
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key) => String(texts[key] || key);
  const esc = (v) => String(v === undefined || v === null ? '' : v)
    .replace(/\\/g, '\\\\')
    .replace(/([_*\[\]()~`>#+\-=|{}.!])/g, '\\$1');
  const replyMarkup = { inline_keyboard: [[{ text: t('onb.btn.continue'), callback_data: 'ob:continue' }]] };
  return { text: esc(t('onb.why')), replyMarkup: replyMarkup, now: new Date().toISOString() };
};

export const code = async (inputs) => {
  return { ignored: true };
};

export const code = async (inputs) => {
  // ADR-0034: онбординг — на первое /start вообще, не только на диплинк
  // события. Гейт один на все роли: пока профиль не заполнен, ни staff,
  // ни owner не видят своего меню — сначала тот же онбординг, что и гость.
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };
  const row = arr(inputs.records).map(flat)[0] || {};
  const profileCompletedAt = String(row.profile_completed_at || '');
  return { needsOnboard: profileCompletedAt === '', profileCompletedAt: profileCompletedAt };
};
